import React, { useState, useMemo, useEffect } from 'react';
import { ArrowDown, ChevronDown, Settings, Eye, Info, Sparkles, StopCircle, LayoutGrid, Clock, Zap, TrendingUp, CheckCircle2 } from 'lucide-react';
import { ComposedChart, Bar, Cell, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { formatMoney, formatToken, formatTokenAmount, EducationalTooltip, ETH_ICON, USDC_ICON } from './Shared';

interface AlgoPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const AlgoPanel: React.FC<AlgoPanelProps> = ({ amount, onAmountChange, balance }) => {
  const [algoStrategy, setAlgoStrategy] = useState<'TWAP' | 'VWAP' | 'ICEBERG'>('TWAP');
  const [algoDuration, setAlgoDuration] = useState(4);
  const [algoMinPrice, setAlgoMinPrice] = useState('');
  const [algoRandomize, setAlgoRandomize] = useState(false);
  const [participationRate, setParticipationRate] = useState(10);
  const [icebergVisibleAmount, setIcebergVisibleAmount] = useState('');

  const [isAlgoRunning, setIsAlgoRunning] = useState(false);
  const [executionProgress, setExecutionProgress] = useState(0);

  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;
  const ETH_PRICE = 3208.93;

  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isAlgoRunning && executionProgress < 100) {
      interval = setInterval(() => {
        setExecutionProgress(prev => Math.min(prev + 0.5, 100));
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isAlgoRunning, executionProgress]);

  const simulation = useMemo(() => {
    const pay = numericPay;
    const usdValue = pay * ETH_PRICE;
    const MIN_TRANCHE_USD = 2000;

    // Default Defaults
    let optimalTranches = 1;
    let avgIntervalMins = 0;
    let hiddenSize = 0;
    let signalingSavings = 0;

    if (algoStrategy === 'ICEBERG' && pay > 0) {
        const visibleAmountNum = parseFloat(icebergVisibleAmount) || (pay * 0.1);
        optimalTranches = Math.ceil(pay / visibleAmountNum);
        if(optimalTranches < 1) optimalTranches = 1;
        avgIntervalMins = 3;
        hiddenSize = Math.max(0, pay - visibleAmountNum);
        signalingSavings = usdValue * 0.0015;
    } else {
        const maxViable = Math.floor(usdValue / MIN_TRANCHE_USD);
        const totalMin = algoDuration * 60;
        optimalTranches = Math.floor(totalMin / 20);
        if(optimalTranches > maxViable) optimalTranches = Math.max(1, maxViable);
        if(optimalTranches < 1) optimalTranches = 1;
        avgIntervalMins = optimalTranches > 0 ? Math.floor(totalMin / optimalTranches) : 0;
    }

    const algoTotalGas = optimalTranches * 9.75;
    const platformFee = usdValue * 0.0005;
    const totalAlgoCost = algoTotalGas + platformFee;

    const swapImpactCost = usdValue * ((usdValue/10000000)*2.85)/100;
    const vwapSavings = swapImpactCost - (usdValue * 0.0005 + algoTotalGas); // Simplified
    const netSavings = Math.max(0, vwapSavings + signalingSavings);

    // Schedule
    const scheduleData = [];
    if(optimalTranches > 0) {
        let currentTime = new Date();
        for(let i=0; i<optimalTranches; i++) {
            scheduleData.push({
                id: i,
                time: currentTime.toLocaleTimeString('en-US', {hour:'2-digit', minute:'2-digit', hour12:false}),
                volume: pay / optimalTranches,
                status: i < 2 ? 'executed' : i === 2 ? 'active' : 'pending'
            });
            currentTime = new Date(currentTime.getTime() + avgIntervalMins*60000);
        }
    }

    return {
        numTranches: optimalTranches,
        avgIntervalMins,
        algoTotalGas,
        platformFee,
        totalAlgoCost,
        netSavings,
        scheduleData,
        swapImpactCost,
        swapImpactPct: ((usdValue/10000000)*2.85).toFixed(2)
    };
  }, [numericPay, algoStrategy, algoDuration, icebergVisibleAmount]);

  const handlePercentageClick = (pct: number) => {
    const maxSafe = Math.max(0, balance - 0.01);
    const val = (maxSafe * pct) / 100;
    onAmountChange(val.toFixed(4));
  };

  return (
    <>
      <section className="lg:col-span-4 flex flex-col h-full gap-4">
         {/* Running State Overlay */}
         {isAlgoRunning ? (
             <div className="flex-1 bg-zinc-900/40 border border-white/5 rounded-2xl p-6 shadow-2xl backdrop-blur-md flex flex-col animate-in fade-in zoom-in-95">
                <div className="flex items-center justify-between mb-6">
                   <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                     <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                     Execution Active
                   </span>
                   <span className="text-[10px] font-mono font-bold text-emerald-400 tabular-nums">{algoStrategy} • {algoStrategy === 'ICEBERG' ? `${simulation.numTranches} Tranches` : `${algoDuration}H`}</span>
                </div>
                <div className="bg-black/40 border border-white/5 rounded-3xl p-6 relative overflow-hidden mb-6">
                    <div className="flex justify-between items-end mb-4 relative z-10">
                        <div>
                           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1">Filled Amount</p>
                           <p className="text-2xl font-mono font-bold text-white tabular-nums">{formatToken((parseFloat(amount) || 0) * (executionProgress/100))} ETH</p>
                        </div>
                        <div className="text-right">
                           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1">Avg Price</p>
                           <p className="text-xl font-mono font-bold text-emerald-500 tabular-nums">$3,205.12</p>
                        </div>
                    </div>
                    <div className="h-3 w-full bg-zinc-800 rounded-full overflow-hidden mb-2 relative z-10">
                       <div className="h-full bg-gradient-to-r from-emerald-600 to-emerald-400 transition-all duration-300" style={{ width: `${executionProgress}%` }}></div>
                    </div>
                    <div className="flex justify-between text-[9px] font-mono text-zinc-500 relative z-10">
                       <span>{executionProgress.toFixed(1)}% Complete</span>
                       <span>~{simulation.avgIntervalMins * (simulation.numTranches - (simulation.numTranches * executionProgress/100))}m Remaining</span>
                    </div>
                </div>
                <button 
                  onClick={() => setIsAlgoRunning(false)}
                  className="mt-auto w-full h-12 rounded-xl font-black text-[11px] uppercase tracking-[0.05em] bg-rose-500/10 text-rose-500 border border-rose-500/20 hover:bg-rose-500 hover:text-white transition-all flex items-center justify-center gap-2"
                >
                  <StopCircle size={16} /> Stop Engine
                </button>
             </div>
         ) : (
             <div className="flex-1 flex flex-col gap-4">
                <div className="bg-zinc-900/40 border border-white/5 rounded-2xl p-6 shadow-2xl backdrop-blur-md">
                    {/* Pay Input */}
                    <div className="space-y-4">
                        <div className="flex justify-between items-start">
                            <div className="flex flex-col gap-2 w-full">
                                 <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest flex justify-between w-full pr-1">
                                    <span>You Pay</span>
                                    <span className="font-mono text-zinc-500">Bal: {formatToken(balance)}</span>
                                 </label>
                                 <div className="flex items-center gap-3">
                                    <input type="text" value={amount} onChange={(e) => onAmountChange(e.target.value)} className="text-4xl lg:text-5xl font-mono font-medium tracking-tighter bg-transparent outline-none placeholder:text-zinc-800 text-white w-full min-w-0" placeholder="0.00" />
                                    <div className="flex items-center gap-2 bg-zinc-950/50 border border-white/10 px-3 py-2 rounded-xl">
                                        <img src={ETH_ICON} className="w-5 h-5 object-contain" alt="ETH" />
                                        <span className="font-bold text-white text-sm">ETH</span>
                                    </div>
                                 </div>
                                 <div className="flex gap-2 mt-1">
                                    {[25, 50, 75, 100].map(pct => (
                                        <button key={pct} onClick={() => handlePercentageClick(pct)} className="border border-white/10 text-[10px] font-bold text-zinc-500 px-3 py-1 rounded-md hover:bg-white/5 hover:text-white transition-colors">
                                            {pct === 100 ? 'MAX' : `${pct}%`}
                                        </button>
                                    ))}
                                 </div>
                            </div>
                        </div>
                        <div className="relative h-px bg-white/5 w-full my-2"><div className="absolute left-1/2 -translate-x-1/2 -top-3 p-1.5 bg-[#0e0e11] border border-white/10 rounded-full text-zinc-500 shadow-sm"><ArrowDown size={12} /></div></div>
                        <div className="flex justify-between items-end">
                            <div className="flex flex-col gap-2 w-full">
                                 <label className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">Estimated Receive</label>
                                 <div className="flex items-center gap-3">
                                    <div className="text-3xl lg:text-4xl font-mono font-medium tracking-tighter text-zinc-300 w-full min-w-0 truncate">
                                        {amount ? formatTokenAmount(numericPay * ETH_PRICE - simulation.totalAlgoCost) : '0.00'}
                                    </div>
                                    <div className="flex items-center gap-2 bg-zinc-950/50 border border-white/5 px-3 py-2 rounded-xl">
                                        <img src={USDC_ICON} className="w-5 h-5 object-contain" alt="USDC" />
                                        <span className="font-bold text-white text-sm">USDC</span>
                                    </div>
                                 </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Algo Config */}
                <div className="bg-zinc-900 border border-white/5 rounded-2xl p-5 flex flex-col gap-6 shadow-inner">
                    <div className="flex items-center justify-between">
                        <span className="text-[10px] font-black text-zinc-400 uppercase tracking-widest">Strategy Parameters</span>
                        <Settings size={12} className="text-zinc-600"/>
                    </div>
                    <div>
                        <div className="bg-black/40 p-1 rounded-lg border border-white/5 flex mb-4">
                            {['TWAP', 'VWAP', 'ICEBERG'].map(strat => (
                                <button key={strat} onClick={() => setAlgoStrategy(strat as any)} className={`flex-1 py-2 rounded-md text-[9px] font-black uppercase tracking-wider transition-all ${algoStrategy === strat ? 'bg-zinc-700 text-white shadow-sm' : 'text-zinc-500 hover:text-zinc-300'}`}>
                                    {strat}
                                </button>
                            ))}
                        </div>
