             </div>
         )}
      </section>

      {/* --- RIGHT PANEL --- */}
      <section className="lg:col-span-6 bg-zinc-900/40 border border-white/5 rounded-2xl p-6 flex flex-col h-full overflow-y-auto scrollbar-hide">
          <h2 className="text-lg font-bold text-white flex items-center gap-2 mb-8"><Sparkles className="w-5 h-5 text-gray-500" /> Execution Simulation</h2>

          <div className="flex-1 flex flex-col space-y-6">
             <div className="bg-black/40 border border-white/5 rounded-2xl p-6 relative overflow-hidden grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="flex flex-col h-full justify-center">
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2">Impact Penalty</span>
                    <span className={`text-3xl font-mono font-bold mb-1 tabular-nums ${numericPay > 0 ? 'text-red-500' : 'text-zinc-500'}`}>{numericPay > 0 ? `-${formatMoney(simulation.swapImpactCost)}` : '$0.00'}</span>
                    <span className="text-[9px] font-bold text-zinc-600 uppercase tabular-nums">If Market Sold</span>
                </div>
                <div className="flex flex-col border-l border-white/5 pl-6 h-full justify-center">
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2 flex items-center gap-1.5"><Sparkles size={10} className="text-emerald-400"/> Alpha Gen</span>
                    <span className={`text-4xl font-mono font-bold mb-1 tabular-nums ${numericPay > 0 ? 'text-white' : 'text-zinc-500'}`}>{numericPay > 0 ? `+${formatMoney(simulation.netSavings)}` : '$0.00'}</span>
                    <span className="text-[9px] font-bold text-zinc-600 uppercase tabular-nums">Capital Preserved</span>
                </div>
                <div className="flex flex-col border-l border-white/5 pl-6 h-full justify-center">
                    <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2">Cost</span>
                    <span className="text-3xl font-mono font-bold mb-1 tabular-nums text-zinc-400">-{formatMoney(simulation.totalAlgoCost)}</span>
                    <span className="text-[9px] font-bold text-zinc-600 uppercase tabular-nums">Fees + Gas</span>
                </div>
             </div>

             <div className="flex-1 min-h-[200px] bg-black/20 border border-white/5 rounded-2xl p-6 flex flex-col">
                <div className="flex justify-between items-center mb-6">
                    <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Execution Schedule</span>
                    <span className="text-[9px] font-mono text-zinc-600">Interval: ~{simulation.avgIntervalMins}m</span>
                </div>
                <div className="flex-1 w-full min-h-[150px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={simulation.scheduleData}>
                            <XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: '#52525b', fontSize: 10, fontWeight: 700 }} interval="preserveStartEnd" />
                            <YAxis hide />
                            <Tooltip cursor={{ fill: 'rgba(255,255,255,0.05)' }} contentStyle={{ backgroundColor: '#09090b', borderColor: '#333' }} />
                            <Bar dataKey="volume" radius={[4, 4, 0, 0]}>
                                {simulation.scheduleData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={entry.status === 'executed' ? '#3f3f46' : entry.status === 'active' ? '#a855f7' : 'transparent'} stroke={entry.status === 'pending' ? '#a855f7' : 'none'} strokeWidth={1} strokeDasharray={entry.status === 'pending' ? '4 4' : '0'} />
                                ))}
                            </Bar>
                        </ComposedChart>
                    </ResponsiveContainer>
                </div>
             </div>
          </div>
      </section>
    </>
  );
};

