import React, { useState, useMemo, useEffect } from 'react';
import { ArrowDown, ChevronDown, Check, ShieldCheck, User, Fuel, Sparkles, GitMerge, AlertTriangle, Lock, RefreshCw, Settings2, ArrowRight } from 'lucide-react';
import { TokenSelectorModal, formatMoney, formatToken, formatTokenAmount, ETH_ICON, USDC_ICON } from './Shared';

interface SwapPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const SwapPanel: React.FC<SwapPanelProps> = ({ amount, onAmountChange, balance }) => {
  const [recipientMode, setRecipientMode] = useState(false);
  const [gasSpeed, setGasSpeed] = useState<'slow' | 'normal' | 'fast'>('normal');
  const [isGasSelectorOpen, setIsGasSelectorOpen] = useState(false);
  const [isTokenSelectorOpen, setIsTokenSelectorOpen] = useState(false);
  const [isReviewing, setIsReviewing] = useState(false);
  const [reviewTimer, setReviewTimer] = useState(15);
  const [slippage, setSlippage] = useState(0.5);

  const ETH_PRICE = 3208.93;
  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;
  const hasAmount = numericPay > 0;

  // Review Timer Logic
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isReviewing) {
        setReviewTimer(15);
        interval = setInterval(() => {
            setReviewTimer(prev => {
                if (prev <= 1) {
                    setIsReviewing(false); 
                    return 15;
                }
                return prev - 1;
            });
        }, 1000);
    }
    return () => clearInterval(interval);
  }, [isReviewing]);

  const simulation = useMemo(() => {
    const pay = numericPay;
    const usdValue = pay * ETH_PRICE;

    // MOCK LIQUIDITY & IMPACT
    const MOCK_LIQUIDITY = 10_000_000; 
    const IMPACT_MULTIPLIER = 2.85; 
    let swapImpactPct = 0;
    if (usdValue > 0) {
        swapImpactPct = (usdValue / MOCK_LIQUIDITY) * IMPACT_MULTIPLIER;
    }
    const platformFee = usdValue * 0.0005;

    let networkFee = 9.75;
    if (gasSpeed === 'fast') networkFee = 12.20;
    if (gasSpeed === 'slow') networkFee = 7.50;

    // Route Logic
    let routeSplit = [];
    const baseRate = ETH_PRICE;
    if (usdValue > 0) {
        if (usdValue < 50000) {
             routeSplit = [{ dex: 'Uniswap V3', pct: 100, color: 'bg-white', rate: baseRate * 1.0005, impact: swapImpactPct * 0.9 }];
        } else {
             routeSplit = [
                { dex: 'Uniswap V3', pct: 70, color: 'bg-white', rate: baseRate * 1.0002, impact: swapImpactPct * 0.8 }, 
                { dex: 'Maverick', pct: 30, color: 'bg-zinc-600', rate: baseRate * 0.9998, impact: swapImpactPct * 1.2 }
             ];
        }
    } else {
        routeSplit = [{ dex: 'Uniswap V3', pct: 100, color: 'bg-white', rate: baseRate, impact: 0.00 }];
    }

    const swapImpactCost = usdValue * (swapImpactPct / 100);
    const totalSwapCost = swapImpactCost + platformFee + networkFee;
    const receiveValNum = Math.max(0, usdValue - totalSwapCost);
    const minReceived = receiveValNum * (1 - slippage/100);

    // Scoring
    let routingScore = 10 - (swapImpactPct * 10);
    if (routingScore < 1) routingScore = 1;
    let scoreColor = 'text-emerald-500';
    let scoreLabel = 'OPTIMAL';
    let progressBarColor = 'bg-emerald-500';
    if (swapImpactPct > 0.3) {
        scoreColor = 'text-amber-500'; scoreLabel = 'FAIR'; progressBarColor = 'bg-amber-500';
    }
    if (swapImpactPct > 1.0) {
        scoreColor = 'text-rose-500'; scoreLabel = 'POOR'; progressBarColor = 'bg-rose-500';
    }

    return {
        receiveValNum,
        minReceived,
        swapImpactPct,
        platformFee,
        networkFee,
        routeSplit,
        routingScore: routingScore.toFixed(1),
        scoreColor,
        scoreLabel,
        progressBarColor
    };
  }, [numericPay, gasSpeed, slippage]);

  const handlePercentageClick = (pct: number) => {
    const maxSafe = Math.max(0, balance - 0.01);
    const val = (maxSafe * pct) / 100;
    onAmountChange(val.toFixed(4));
  };

  return (
    <>
      <TokenSelectorModal isOpen={isTokenSelectorOpen} onClose={() => setIsTokenSelectorOpen(false)} onSelect={(t: string) => console.log(t)} />

      {/* --- LEFT PANEL: INPUT --- */}
      <section className="lg:col-span-4 flex flex-col h-full gap-5">

         {/* Main Card */}
         <div className={`bg-zinc-900/40 border border-white/5 rounded-[2.5rem] p-2 shadow-2xl backdrop-blur-md relative overflow-hidden transition-all duration-300 ${isReviewing ? 'opacity-50 pointer-events-none grayscale-[0.5]' : ''}`}>

            <div className="bg-[#0a0a0a] rounded-[2.2rem] p-6 border border-white/5 space-y-2">

                {/* 1. PAY BLOCK */}
                <div className="bg-[#050505] rounded-3xl p-5 border border-white/5 focus-within:border-emerald-500/30 transition-colors group">
                    <div className="flex justify-between items-start mb-4">
                        <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] group-focus-within:text-emerald-500 transition-colors">You Pay</label>
                        <div className="text-[9px] font-bold text-zinc-500 bg-zinc-900 px-2 py-1 rounded-lg border border-white/5 flex items-center gap-2">
                            <span>Bal: <span className="font-mono text-zinc-300">{formatToken(balance)}</span></span>
                            <button onClick={() => handlePercentageClick(100)} className="text-emerald-500 hover:text-emerald-400 font-black text-[8px] uppercase">Max</button>
                        </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <input 
                            type="text" 
                            value={amount}
                            onChange={(e) => onAmountChange(e.target.value)}
                            className="w-full bg-transparent text-4xl lg:text-5xl font-mono font-medium tracking-tighter text-white placeholder:text-zinc-800 focus:outline-none" 
                            placeholder="0.00" 
                        />
                        <button 
                            onClick={() => setIsTokenSelectorOpen(true)}
                            className="flex items-center gap-2 bg-zinc-900 border border-white/10 pl-2 pr-3 py-2 rounded-xl hover:bg-zinc-800 transition-all shrink-0 active:scale-95"
                        >
                            <div className="w-6 h-6 rounded-full bg-black border border-white/10 flex items-center justify-center p-0.5">
                                <img src={ETH_ICON} className="w-full h-full object-contain" alt="ETH" />
                            </div>
                            <span className="font-bold text-white text-sm">ETH</span>
                            <ChevronDown size={12} className="text-zinc-500" />
                        </button>
                    </div>

                    <div className="flex justify-between items-center mt-3">
                        <div className="text-xs font-mono font-bold text-zinc-600">
                            ≈ {amount ? formatMoney(numericPay * ETH_PRICE) : '$0.00'}
                        </div>
                        <div className="flex gap-1">
                            {[25, 50].map(pct => (
                                <button key={pct} onClick={() => handlePercentageClick(pct)} className="text-[9px] font-bold text-zinc-600 hover:text-zinc-300 bg-zinc-900/50 px-2 py-1 rounded border border-white/5 transition-colors">
                                    {pct}%
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* CONNECTOR */}
                <div className="relative h-4 w-full flex items-center justify-center z-10 -my-3">
                    <div className="p-1.5 bg-[#0a0a0a] rounded-full border border-white/10 shadow-xl">
                        <div className="bg-zinc-900 p-1.5 rounded-full text-zinc-500 hover:text-emerald-500 transition-colors cursor-pointer">
                            <ArrowDown size={14} strokeWidth={3} />
                        </div>
                    </div>
                </div>

                {/* 2. RECEIVE BLOCK */}
                <div className="bg-[#050505] rounded-3xl p-5 border border-white/5 focus-within:border-emerald-500/30 transition-colors group">
                    <div className="flex justify-between items-start mb-4">
                        <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] group-focus-within:text-emerald-500 transition-colors">
                            {recipientMode ? "Recipient Gets" : "You Receive"}
                        </label>
                        {recipientMode && <span className="text-[9px] font-bold text-emerald-500 uppercase tracking-widest bg-emerald-500/10 px-2 py-0.5 rounded">Custom Address</span>}
                    </div>

                    <div className="flex items-center gap-4">
                        <div className={`w-full text-4xl lg:text-5xl font-mono font-medium tracking-tighter truncate ${hasAmount ? 'text-emerald-400' : 'text-zinc-800'}`}>
                            {amount ? formatTokenAmount(simulation.receiveValNum) : '0.00'}
                        </div>
                        <button className="flex items-center gap-2 bg-zinc-900 border border-white/10 pl-2 pr-3 py-2 rounded-xl hover:bg-zinc-800 transition-all shrink-0 active:scale-95">
                            <div className="w-6 h-6 rounded-full bg-black border border-white/10 flex items-center justify-center p-0.5">
                                <img src={USDC_ICON} className="w-full h-full object-contain" alt="USDC" />
                            </div>
                            <span className="font-bold text-white text-sm">USDC</span>
                            <ChevronDown size={12} className="text-zinc-500" />
                        </button>
                    </div>

                    <div className="flex justify-between items-center mt-3">
                        <div className="text-xs font-mono font-bold text-zinc-600">
                            ≈ {amount ? formatMoney(simulation.receiveValNum) : '$0.00'}
                        </div>
                        <div className="text-[9px] font-mono font-bold text-zinc-600 flex items-center gap-1">
                            <span className="text-zinc-500">Rate:</span> 1 ETH ≈ {ETH_PRICE.toLocaleString()} USDC
                        </div>
                    </div>
                </div>

                {/* 3. RECIPIENT TOGGLE */}
                <div className="px-2 pt-2">
                    <button 
                        onClick={() => setRecipientMode(!recipientMode)} 
                        className="flex items-center gap-2 text-zinc-500 hover:text-zinc-300 transition-colors group w-full"
                    >
                        <div className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${recipientMode ? 'bg-emerald-500 border-emerald-500 text-black' : 'border-zinc-700 bg-transparent'}`}>
                            {recipientMode && <Check size={10} strokeWidth={4} />}
                        </div>
                        <span className="text-[10px] font-bold uppercase tracking-widest">Send to wallet</span>
                    </button>

                    {recipientMode && (
                        <div className="mt-3 relative animate-in fade-in slide-in-from-top-1">
                            <input 
                                type="text" 
                                placeholder="0x..." 
                                className="w-full bg-[#050505] border border-white/10 rounded-xl py-3 pl-10 pr-4 text-xs font-mono text-white focus:outline-none focus:border-emerald-500/50" 
                            />
                            <div className="absolute left-3.5 top-1/2 -translate-y-1/2 text-zinc-600">
                                <User size={14} />
                            </div>
                        </div>
                    )}
                </div>

            </div>

            {/* Review Overlay */}
            {isReviewing && (
                <div className="absolute inset-0 flex items-center justify-center z-20 animate-in fade-in zoom-in-95 duration-200">
                    <div className="bg-black/90 backdrop-blur-md absolute inset-0"></div>
                    <div className="relative bg-[#09090b] border border-white/10 p-6 rounded-3xl shadow-2xl max-w-xs w-full text-center">
                        <div className="w-12 h-12 bg-emerald-500/20 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-emerald-500/20">
                            <Lock size={20} />
                        </div>
                        <h3 className="text-white font-bold text-lg mb-1">Confirm Swap</h3>
                        <p className="text-zinc-400 text-xs mb-6">Rate expires in <span className="text-emerald-500 font-mono">{reviewTimer}s</span></p>

                        <div className="space-y-2">
                            <button 
                                onClick={() => { console.log('Swap Executed'); setIsReviewing(false); }}
                                className="w-full py-3 bg-emerald-500 text-black rounded-xl font-black text-xs uppercase tracking-[0.2em] hover:bg-emerald-400 transition-all shadow-[0_0_20px_rgba(16,185,129,0.3)] active:scale-95"
                            >
                                Sign & Swap
                            </button>
                            <button 
                                onClick={() => setIsReviewing(false)}
                                className="w-full py-3 bg-transparent text-zinc-500 hover:text-white rounded-xl font-bold text-xs uppercase tracking-widest transition-colors"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}
         </div>

         {/* Execution Details Ticket */}
         <div className="bg-zinc-900/40 border border-white/5 rounded-[2rem] p-6 shadow-inner space-y-4">
             <div className="flex justify-between items-center pb-3 border-b border-dashed border-white/10">
                 <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-1.5">
                     <Fuel size={12} /> Network Cost
                 </span>
                 <div className="text-right">
