import React from 'react';

interface GlassPanelProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
}

/**
 * GlassPanel Atom
 * 
 * Represents the "Level 1" surface for main interactive areas like Swaps and Charts.
