import React, { useState, useMemo, useEffect } from 'react';
import { ArrowDown, ChevronDown, Check, ShieldCheck, User, Fuel, Sparkles, GitMerge, AlertTriangle, Lock, Settings2, ArrowRight, Zap, RefreshCw, AlertOctagon } from 'lucide-react';
import { TokenSelectorModal, formatMoney, formatToken, formatTokenAmount, getTokenLogo } from './Shared';
import { GlassPanel } from '../ui/GlassPanel';

interface SwapPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const SwapPanel: React.FC<SwapPanelProps> = ({ amount, onAmountChange, balance }) => {
  // --- STATE PERSISTENCE & DATA ---
  const [recipientMode, setRecipientMode] = useState(false);
  const [recipientAddress, setRecipientAddress] = useState(''); // Persist even if toggled off
  const [gasSpeed, setGasSpeed] = useState<'slow' | 'normal' | 'fast'>('normal');
  const [isGasSelectorOpen, setIsGasSelectorOpen] = useState(false);

  // Token State
  const [payToken, setPayToken] = useState({ sym: 'ETH', name: 'Ethereum' });
  const [receiveToken, setReceiveToken] = useState({ sym: 'USDC', name: 'USD Coin' });
  const [selectingSide, setSelectingSide] = useState<'pay' | 'receive' | null>(null);

  // Settings State (Intelligence Panel)
  const [slippage, setSlippage] = useState(0.5);
  const [useMEVShield, setUseMEVShield] = useState(true);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false); // Controls the Intelligence details view

  // UX State
  const [isReviewing, setIsReviewing] = useState(false);
  const [reviewTimer, setReviewTimer] = useState(15);
  const [isSimulating, setIsSimulating] = useState(false);

  const ETH_PRICE = 3208.93;
  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;
  const hasAmount = numericPay > 0;

  // --- EFFECT: Simulate Route Calculation when Amount Changes ---
  useEffect(() => {
      if (hasAmount) {
          setIsSimulating(true);
          const timer = setTimeout(() => setIsSimulating(false), 800); // Fake latency
          return () => clearTimeout(timer);
      }
  }, [amount, payToken, receiveToken]);

  // --- REVIEW TIMER ---
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isReviewing) {
        setReviewTimer(15);
        interval = setInterval(() => {
            setReviewTimer(prev => {
                if (prev <= 1) {
                    setIsReviewing(false); 
                    return 15;
                }
                return prev - 1;
            });
        }, 1000);
    }
    return () => clearInterval(interval);
  }, [isReviewing]);

  // --- CORE LOGIC ---
  const simulation = useMemo(() => {
    const pay = numericPay;
    const usdValue = pay * ETH_PRICE; // Simplified assumption for demo

    // MOCK LIQUIDITY & IMPACT
    const MOCK_LIQUIDITY = 10_000_000; 
    const IMPACT_MULTIPLIER = 2.85; 
    let swapImpactPct = 0;
    if (usdValue > 0) {
        swapImpactPct = (usdValue / MOCK_LIQUIDITY) * IMPACT_MULTIPLIER;
    }
    const platformFee = usdValue * 0.0005;

    let networkFee = 9.75;
    if (gasSpeed === 'fast') networkFee = 12.20;
    if (gasSpeed === 'slow') networkFee = 7.50;

    // Route Logic (Visualization)
    let routeSplit = [];
    const baseRate = ETH_PRICE;
    if (usdValue > 0) {
        if (usdValue < 50000) {
             routeSplit = [{ dex: 'Uniswap V3', pct: 100, color: 'bg-white', rate: baseRate * 1.0005, impact: swapImpactPct * 0.9 }];
        } else {
             routeSplit = [
                { dex: 'Uniswap V3', pct: 70, color: 'bg-white', rate: baseRate * 1.0002, impact: swapImpactPct * 0.8 }, 
                { dex: 'Maverick', pct: 30, color: 'bg-zinc-600', rate: baseRate * 0.9998, impact: swapImpactPct * 1.2 }
             ];
        }
    } else {
        routeSplit = [{ dex: 'Uniswap V3', pct: 100, color: 'bg-white', rate: baseRate, impact: 0.00 }];
    }

    const swapImpactCost = usdValue * (swapImpactPct / 100);
    const totalSwapCost = swapImpactCost + platformFee + networkFee;
    const receiveValNum = Math.max(0, usdValue - totalSwapCost);
    const minReceived = receiveValNum * (1 - slippage/100);

    // Scoring
    let routingScore = 10 - (swapImpactPct * 10);
    if (routingScore < 1) routingScore = 1;
    let scoreColor = 'text-emerald-500';
    let scoreLabel = 'OPTIMAL';
    let progressBarColor = 'bg-emerald-500';
    if (swapImpactPct > 0.3) {
        scoreColor = 'text-amber-500'; scoreLabel = 'FAIR'; progressBarColor = 'bg-amber-500';
    }
    if (swapImpactPct > 1.0) {
        scoreColor = 'text-rose-500'; scoreLabel = 'POOR'; progressBarColor = 'bg-rose-500';
    }

    return {
        receiveValNum,
        minReceived,
        swapImpactPct,
        platformFee,
        networkFee,
        routeSplit,
        routingScore: routingScore.toFixed(1),
        scoreColor,
        scoreLabel,
        progressBarColor
    };
  }, [numericPay, gasSpeed, slippage]);

  const handlePercentageClick = (pct: number) => {
    const maxSafe = Math.max(0, balance - 0.01);
    const val = (maxSafe * pct) / 100;
    onAmountChange(val.toFixed(4));
  };

  const handleTokenSelect = (token: any) => {
      if (selectingSide === 'pay') setPayToken(token);
      if (selectingSide === 'receive') setReceiveToken(token);
      setSelectingSide(null);
  };

  const handleFlip = () => {
      const tempToken = payToken;
      setPayToken(receiveToken);
      setReceiveToken(tempToken);
      // Note: Logic would typically flip amounts too based on rate, simplified here.
  };

  return (
    <>
      <TokenSelectorModal isOpen={!!selectingSide} onClose={() => setSelectingSide(null)} onSelect={handleTokenSelect} />

      {/* --- LEFT PANEL: INPUT --- */}
      <section className="lg:col-span-4 flex flex-col h-full gap-5">

         {/* Main Card: Utilizes new GlassPanel Atom */}
         <GlassPanel className={`p-2 ${isReviewing ? 'opacity-50 pointer-events-none grayscale-[0.5]' : ''}`}>

            <div className="bg-[#0a0a0a] rounded-[2.2rem] p-6 border border-white/5 space-y-2">

                {/* 1. PAY BLOCK */}
                <div className="bg-[#050505] rounded-3xl p-5 border border-white/5 focus-within:border-emerald-500/30 transition-colors group relative">
                    <div className="flex justify-between items-start mb-4">
                        <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] group-focus-within:text-emerald-500 transition-colors">You Pay</label>
                        <div className="text-[9px] font-bold text-zinc-500 bg-zinc-900 px-2 py-1 rounded-lg border border-white/5 flex items-center gap-2">
                            <span>Bal: <span className="font-mono text-zinc-300">{formatToken(balance)}</span></span>
                            <button onClick={() => handlePercentageClick(100)} className="text-emerald-500 hover:text-emerald-400 font-black text-[8px] uppercase">Max</button>
                        </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <input 
                            type="text" 
                            value={amount}
                            onChange={(e) => onAmountChange(e.target.value)}
                            className="w-full bg-transparent text-4xl lg:text-5xl font-mono font-medium tracking-tighter text-white placeholder:text-zinc-800 focus:outline-none" 
                            placeholder="0.00" 
                        />
                        <button 
                            onClick={() => setSelectingSide('pay')}
                            className="flex items-center gap-2 bg-zinc-900 border border-white/10 pl-2 pr-3 py-2 rounded-xl hover:bg-zinc-800 transition-all shrink-0 active:scale-95"
                        >
                            <div className="w-6 h-6 rounded-full bg-black border border-white/10 flex items-center justify-center p-0.5">
                                <img src={getTokenLogo(payToken.sym)} className="w-full h-full object-contain" alt={payToken.sym} />
                            </div>
                            <span className="font-bold text-white text-sm">{payToken.sym}</span>
                            <ChevronDown size={12} className="text-zinc-500" />
                        </button>
                    </div>

                    <div className="flex justify-between items-center mt-3">
                        <div className="text-xs font-mono font-bold text-zinc-600">
                            ≈ {amount ? formatMoney(numericPay * ETH_PRICE) : '$0.00'}
                        </div>
                        <div className="flex gap-1">
                            {[25, 50].map(pct => (
                                <button key={pct} onClick={() => handlePercentageClick(pct)} className="text-[9px] font-bold text-zinc-600 hover:text-zinc-300 bg-zinc-900/50 px-2 py-1 rounded border border-white/5 transition-colors">
                                    {pct}%
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* CONNECTOR */}
                <div className="relative h-4 w-full flex items-center justify-center z-10 -my-3">
                    <div className="p-1.5 bg-[#0a0a0a] rounded-full border border-white/10 shadow-xl">
                        <div onClick={handleFlip} className="bg-zinc-900 p-1.5 rounded-full text-zinc-500 hover:text-emerald-500 transition-colors cursor-pointer active:rotate-180 duration-300">
                            <ArrowDown size={14} strokeWidth={3} />
                        </div>
                    </div>
                </div>

                {/* 2. RECEIVE BLOCK */}
                <div className="bg-[#050505] rounded-3xl p-5 border border-white/5 focus-within:border-emerald-500/30 transition-colors group">
                    <div className="flex justify-between items-start mb-4">
                        <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] group-focus-within:text-emerald-500 transition-colors">
                            {recipientMode ? "Recipient Gets" : "You Receive"}
                        </label>
                        {recipientMode && <span className="text-[9px] font-bold text-emerald-500 uppercase tracking-widest bg-emerald-500/10 px-2 py-0.5 rounded">Custom Address</span>}
                    </div>

                    <div className="flex items-center gap-4">
                        <div className={`w-full text-4xl lg:text-5xl font-mono font-medium tracking-tighter truncate ${hasAmount ? 'text-emerald-400' : 'text-zinc-800'}`}>
                            {isSimulating ? <span className="animate-pulse opacity-50">Calculating...</span> : amount ? formatTokenAmount(simulation.receiveValNum) : '0.00'}
                        </div>
                        <button 
                            onClick={() => setSelectingSide('receive')}
                            className="flex items-center gap-2 bg-zinc-900 border border-white/10 pl-2 pr-3 py-2 rounded-xl hover:bg-zinc-800 transition-all shrink-0 active:scale-95"
                        >
                            <div className="w-6 h-6 rounded-full bg-black border border-white/10 flex items-center justify-center p-0.5">
                                <img src={getTokenLogo(receiveToken.sym)} className="w-full h-full object-contain" alt={receiveToken.sym} />
                            </div>
                            <span className="font-bold text-white text-sm">{receiveToken.sym}</span>
                            <ChevronDown size={12} className="text-zinc-500" />
                        </button>
                    </div>

                    <div className="flex justify-between items-center mt-3">
                        <div className="text-xs font-mono font-bold text-zinc-600">
                            ≈ {amount ? formatMoney(simulation.receiveValNum) : '$0.00'}
                        </div>
                        <div className="text-[9px] font-mono font-bold text-zinc-600 flex items-center gap-1">
                            <span className="text-zinc-500">Rate:</span> 1 {payToken.sym} ≈ {ETH_PRICE.toLocaleString()} {receiveToken.sym}
                        </div>
                    </div>
                </div>

                {/* 3. RECIPIENT TOGGLE */}
                <div className="px-2 pt-2">
                    <button 
                        onClick={() => setRecipientMode(!recipientMode)} 
                        className="flex items-center gap-2 text-zinc-500 hover:text-zinc-300 transition-colors group w-full"
                    >
                        <div className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${recipientMode ? 'bg-emerald-500 border-emerald-500 text-black' : 'border-zinc-700 bg-transparent'}`}>
                            {recipientMode && <Check size={10} strokeWidth={4} />}
                        </div>
                        <span className="text-[10px] font-bold uppercase tracking-widest">Send to wallet</span>
                    </button>

                    {/* Persist input even if hidden to prevent data loss (audit fix) */}
                    <div className={`mt-3 relative transition-all duration-300 ${recipientMode ? 'opacity-100 max-h-20' : 'opacity-0 max-h-0 overflow-hidden'}`}>
                        <input 
                            type="text" 
                            value={recipientAddress}
                            onChange={(e) => setRecipientAddress(e.target.value)}
                            placeholder="0x..." 
                            className="w-full bg-[#050505] border border-white/10 rounded-xl py-3 pl-10 pr-4 text-xs font-mono text-white focus:outline-none focus:border-emerald-500/50" 
                        />
                        <div className="absolute left-3.5 top-3.5 text-zinc-600">
                            <User size={14} />
                        </div>
                    </div>
                </div>

            </div>

            {/* Review Overlay */}
            {isReviewing && (
                <div className="absolute inset-0 flex items-center justify-center z-20 animate-in fade-in zoom-in-95 duration-200">
                    <div className="bg-black/90 backdrop-blur-md absolute inset-0"></div>
                    <div className="relative bg-[#09090b] border border-white/10 p-6 rounded-3xl shadow-2xl max-w-xs w-full text-center">
                        <div className="w-12 h-12 bg-emerald-500/20 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-emerald-500/20">
                            <Lock size={20} />
                        </div>
                        <h3 className="text-white font-bold text-lg mb-1">Confirm Swap</h3>
                        <p className="text-zinc-400 text-xs mb-6">Rate expires in <span className="text-emerald-500 font-mono">{reviewTimer}s</span></p>

                        <div className="space-y-2">
                            <button 
                                onClick={() => { console.log('Swap Executed'); setIsReviewing(false); }}
                                className="w-full py-3 bg-emerald-500 text-black rounded-xl font-black text-xs uppercase tracking-[0.2em] hover:bg-emerald-400 transition-all shadow-[0_0_20px_rgba(16,185,129,0.3)] active:scale-95"
                            >
                                Sign & Swap
                            </button>
                            <button 
                                onClick={() => setIsReviewing(false)}
                                className="w-full py-3 bg-transparent text-zinc-500 hover:text-white rounded-xl font-bold text-xs uppercase tracking-widest transition-colors"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}
         </GlassPanel>

         {/* Execution Details Ticket */}
         <div className="bg-zinc-900/40 border border-white/5 rounded-[2rem] p-6 shadow-inner space-y-4">
             <div className="flex justify-between items-center pb-3 border-b border-dashed border-white/10">
                 <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-1.5">
                     <Fuel size={12} /> Network Cost
                 </span>
                 <div className="text-right">
                     <span className="text-xs font-mono font-bold text-white block">~{formatMoney(simulation.networkFee)}</span>
                     <div className="relative group inline-block">
                         <span className="text-[9px] text-zinc-500 font-bold uppercase tracking-wider cursor-pointer hover:text-white transition-colors border-b border-zinc-700 hover:border-white">
                             {gasSpeed}
                         </span>
                         <select 
                            value={gasSpeed}
                            onChange={(e) => setGasSpeed(e.target.value as any)}
                            className="absolute inset-0 opacity-0 cursor-pointer"
                         >
                             <option value="slow">Slow</option>
                             <option value="normal">Normal</option>
                             <option value="fast">Fast</option>
                         </select>
                     </div>
                 </div>
             </div>

             <div className="flex justify-between items-center pb-3 border-b border-dashed border-white/10">
                 <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Price Impact</span>
                 <span className={`text-xs font-mono font-bold ${hasAmount ? 'text-red-400' : 'text-zinc-600'}`}>
                     {hasAmount ? `-${simulation.swapImpactPct.toFixed(2)}%` : '—'}
                 </span>
             </div>

             <div className="flex justify-between items-center">
                 <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest">Min. Received</span>
                 <span className="text-xs font-mono font-bold text-emerald-400">
                     {amount ? formatTokenAmount(simulation.minReceived) : '0.00'} {receiveToken.sym}
                 </span>
             </div>
         </div>

         {/* MAIN ACTION BUTTON */}
         <button 
            onClick={() => setIsReviewing(true)}
            disabled={numericPay <= 0 || isInsufficientBalance}
            className={`w-full py-5 rounded-xl font-black text-xs uppercase tracking-[0.2em] transition-all shadow-xl active:scale-[0.98] ${
                isInsufficientBalance || numericPay <= 0 
                    ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed border border-white/5' 
                    : 'bg-emerald-500 text-black hover:bg-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.2)]' 
            }`}
         >
            {isInsufficientBalance ? 'Insufficient Balance' : numericPay <= 0 ? 'Enter Amount' : 'Review Swap'}
         </button>

      </section>

      {/* --- RIGHT PANEL: INTELLIGENCE --- */}
      <section className="lg:col-span-6 bg-zinc-900/40 border border-white/5 rounded-[2.5rem] p-8 flex flex-col h-full overflow-hidden relative">
          {/* ... Intelligence content remains unchanged for this update ... */}
          {/* Header */}
          <div className="flex justify-between items-start mb-8">
            <div>
                <h2 className="text-xl font-black text-white uppercase tracking-tight flex items-center gap-2">
                   <Sparkles className="text-purple-500" size={20} /> Execution Intelligence
                </h2>
                <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mt-1">AI-Optimized Routing Engine</p>
            </div>
            <div className={`px-3 py-1 rounded-full border text-[9px] font-black uppercase tracking-wider flex items-center gap-2 ${isSimulating ? 'bg-amber-500/10 border-amber-500/20 text-amber-500' : hasAmount ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-zinc-800 border-white/5 text-zinc-500'}`}>
                {isSimulating ? <RefreshCw size={10} className="animate-spin" /> : hasAmount ? <Zap size={10} /> : null}
                {isSimulating ? 'Scanning' : hasAmount ? 'Optimized' : 'Standby'}
            </div>
          </div>

          <div className="flex flex-col gap-6">

             {/* Score Card */}
             <div className="flex items-center gap-6">
                <div className="relative w-24 h-24 flex items-center justify-center shrink-0">
                    {/* Progress Circle Mockup */}
                    <svg className="w-full h-full -rotate-90">
                        <circle cx="48" cy="48" r="40" stroke="#27272a" strokeWidth="6" fill="transparent" />
                        <circle 
                            cx="48" cy="48" r="40" stroke={isSimulating ? '#f59e0b' : '#10b981'} strokeWidth="6" fill="transparent" 
                            strokeDasharray="251.2" 
                            strokeDashoffset={251.2 - (251.2 * (parseFloat(simulation.routingScore) / 10))} 
                            className="transition-all duration-1000 ease-out"
                        />
                    </svg>
                    <div className="absolute inset-0 flex flex-col items-center justify-center">
                        <span className="text-2xl font-mono font-black text-white">{hasAmount && !isSimulating ? simulation.routingScore : '--'}</span>
                        <span className="text-[8px] font-bold text-zinc-500 uppercase">Score</span>
                    </div>
                </div>
                <div className="flex-1 space-y-2">
                    <div className="flex justify-between items-center p-3 bg-black/20 rounded-xl border border-white/5">
                        <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-wider">Route Efficiency</span>
                        <span className="text-[10px] font-mono font-bold text-emerald-400">98.5%</span>
                    </div>
                    <div className="flex justify-between items-center p-3 bg-black/20 rounded-xl border border-white/5">
                        <span className="text-[9px] font-bold text-zinc-500 uppercase tracking-wider">Gas Optimization</span>
                        <span className="text-[10px] font-mono font-bold text-emerald-400">High</span>
                    </div>
                </div>
             </div>

             {/* Route Visualization - NODE BASED */}
             <div className="bg-[#0a0a0a] border border-white/5 rounded-2xl p-5 flex flex-col relative overflow-hidden flex-1 min-h-[240px]">

                <div className="flex items-center justify-between mb-6 relative z-10">
                    <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                       <GitMerge size={12} /> Smart Route
                    </span>
                    <span className="text-[9px] font-mono text-zinc-600">Latency: 2ms</span>
                </div>

                {!hasAmount && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-20">
                        <div className="bg-zinc-900 border border-white/10 px-4 py-2 rounded-xl text-[10px] font-bold text-zinc-400 uppercase tracking-widest">
                            Enter amount to simulate
                        </div>
                    </div>
                )}

                <div className="space-y-4 relative z-10">
                    {/* Source Node */}
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 bg-zinc-900 px-3 py-1.5 rounded-lg border border-white/5">
                            <img src={getTokenLogo(payToken.sym)} className="w-4 h-4 rounded-full" />
                            <span className="text-[10px] font-bold text-white">{payToken.sym}</span>
                        </div>
                        <span className="text-[9px] font-mono text-zinc-500">100%</span>
                    </div>

                    {/* Routing Split */}
                    <div className="flex flex-col gap-2 pl-4 border-l border-zinc-800 ml-4 py-2">
                        {simulation.routeSplit.map((route, idx) => (
                            <div key={idx} className="flex items-center gap-3 relative">
                                <div className="w-4 h-px bg-zinc-800 absolute -left-4"></div>
                                <div className="flex-1 bg-[#121212] border border-white/5 rounded-lg p-2 flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <div className={`w-1.5 h-1.5 rounded-full ${route.color === 'bg-white' ? 'bg-emerald-500' : 'bg-purple-500'}`}></div>
                                        <span className="text-[10px] font-bold text-zinc-300">{route.dex}</span>
                                    </div>
                                    <span className="text-[10px] font-mono text-zinc-500">{route.pct}%</span>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Dest Node */}
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 bg-zinc-900 px-3 py-1.5 rounded-lg border border-white/5">
                            <img src={getTokenLogo(receiveToken.sym)} className="w-4 h-4 rounded-full" />
                            <span className="text-[10px] font-bold text-white">{receiveToken.sym}</span>
                        </div>
                    </div>
                </div>

                {/* Advanced Settings Drawer */}
                <div className={`mt-auto border-t border-white/5 bg-[#0e0e0e] -mx-5 -mb-5 p-5 transition-all duration-300 ${isSettingsOpen ? 'h-auto' : 'h-14'}`}>
                    <div className="flex items-center justify-between cursor-pointer" onClick={() => setIsSettingsOpen(!isSettingsOpen)}>
                        <div className="flex items-center gap-2 text-[9px] text-emerald-500 font-bold uppercase tracking-wider">
                            <ShieldCheck size={12} /> MEV Protected
                        </div>
                        <button className="text-[9px] font-bold text-zinc-500 hover:text-white flex items-center gap-1 transition-colors">
                            <Settings2 size={10} /> Configure <ChevronDown size={10} className={`transition-transform ${isSettingsOpen ? 'rotate-180' : ''}`} />
                        </button>
                    </div>

                    {isSettingsOpen && (
                        <div className="mt-4 grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-bottom-1">
                            <div>
                                <label className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest block mb-2">Max Slippage</label>
                                <div className="flex items-center gap-2">
                                    {[0.1, 0.5, 1.0].map(s => (
                                        <button 
                                            key={s} 
                                            onClick={() => setSlippage(s)}
                                            className={`px-2 py-1 rounded text-[9px] font-bold border ${slippage === s ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-500' : 'bg-zinc-900 border-white/5 text-zinc-500'}`}
                                        >
                                            {s}%
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label className="text-[9px] font-bold text-zinc-500 uppercase tracking-widest block mb-2">Private RPC</label>
                                <button 
                                    onClick={() => setUseMEVShield(!useMEVShield)}
                                    className={`w-full py-1.5 rounded flex items-center justify-center gap-2 text-[9px] font-bold border transition-colors ${useMEVShield ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-500' : 'bg-zinc-900 border-white/5 text-zinc-500'}`}
                                >
                                    {useMEVShield ? 'Enabled' : 'Disabled'}
                                    {useMEVShield ? <Check size={10} /> : <AlertOctagon size={10} />}
                                </button>
                            </div>
                        </div>
                    )}
                </div>
             </div>
          </div>
      </section>
    </>
  );
};

export default SwapPanel;
